package studyfix.assignment.catalog;
import studyfix.assignment.model.*;
import studyfix.assignment.persistence.ProblemTemplate;
import java.io.*;
import java.nio.charset.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
import java.math.BigDecimal;
import static studyfix.assignment.protocol.AssignmentJson.*;

/** Validates the operator package without extracting or executing its contents. */
public final class OjPackage {
 public record Problem(String code,int week,String structure,String entryFile,Exercise exercise,Map<String,Object> config,Map<String,Object> metadata){}
 public final List<Problem> problems;public final List<Map<String,Object>> weeks;public final String sha256;public final int tests;
 private final Map<String,byte[]> files=new LinkedHashMap<>();
 public OjPackage(byte[] zip)throws Exception{
  sha256=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(zip));
  if(zip.length>16*1024*1024)throw new IllegalArgumentException("Gói ZIP tối đa 16 MiB.");ProblemTemplate.validateArchive(zip,4000);int total=0;
  try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(zip),StandardCharsets.UTF_8)){ZipEntry entry;while((entry=in.getNextEntry())!=null){String name=entry.getName();if(!name.matches("[A-Za-z0-9_./-]+")||name.startsWith("/")||Arrays.stream(name.split("/",-1)).anyMatch(x->x.equals(".")||x.equals("..")))throw new IllegalArgumentException("Đường dẫn ZIP không an toàn.");if(entry.isDirectory()){if(in.readNBytes(1).length!=0)throw new IllegalArgumentException("Directory entry contains data");continue;}if(files.size()>=4000)throw new IllegalArgumentException("Quá nhiều file ZIP.");byte[] data=in.readNBytes(1024*1024+1);total+=data.length;if(data.length>1024*1024||total>20*1024*1024||files.putIfAbsent(name,data)!=null)throw new IllegalArgumentException("File trùng hoặc ZIP vượt giới hạn giải nén.");}}
  List<String> manifests=files.keySet().stream().filter(n->n.endsWith("/manifest.json")||n.equals("manifest.json")).toList();if(manifests.size()!=1)throw new IllegalArgumentException("Cần đúng một manifest.json.");String root=manifests.getFirst().replaceFirst("manifest.json$","");Map<String,Object> manifest=object(textFile(root+"manifest.json"));
  if(Boolean.TRUE.equals(manifest.get("categories_enabled")))throw new IllegalArgumentException("Hệ thống dùng Week và dạng bài, không hỗ trợ module Category.");
  weeks=new ArrayList<>();if(files.containsKey(root+"weeks.json")){Object rawWeeks=parse(textFile(root+"weeks.json"));if(!(rawWeeks instanceof List<?>))throw new IllegalArgumentException("weeks.json phải là danh sách.");for(Object item:list(rawWeeks))weeks.add(map(item));}
  Map<String,Integer> mapping=new HashMap<>();Set<Integer> numbers=new HashSet<>();for(var week:weeks){int n=integer(week,"week_number",0);if(n<1||!numbers.add(n))throw new IllegalArgumentException("Week trùng/không hợp lệ.");for(Object code:list(week.get("problem_ids")))if(mapping.put(String.valueOf(code),n)!=null)throw new IllegalArgumentException("Một bài thuộc nhiều Week trong gói.");}
  if(!(manifest.get("problems") instanceof List<?>))throw new IllegalArgumentException("manifest.json phải có danh sách problems.");
  List<Problem> parsed=new ArrayList<>();Set<String> ids=new HashSet<>();int count=0;
  for(Object item:list(manifest.get("problems"))){Map<String,Object> header=map(item);String code=text(header,"id","");if(!code.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,63}")||!ids.add(code))throw new IllegalArgumentException("Mã bài trùng hoặc sai định dạng (chữ, số, _ và -, tối đa 64 ký tự).");String dir=root+"problems/"+code+"/";Map<String,Object> meta=object(textFile(dir+"problem.json")),config=object(textFile(local(dir,text(meta,"judge_config",""))));int week=integer(meta,"week",0);String structure=text(meta,"java_structure","").toUpperCase(Locale.ROOT);
   if(!code.equals(meta.get("id"))||week<0||!Objects.equals(mapping.getOrDefault(code,0),week)||!Set.of("PROGRAM","METHOD","CLASS").contains(structure)||!structure.equals(text(config,"structure","").toUpperCase(Locale.ROOT))||!structure.equals(text(header,"java_structure","").toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("Metadata/Week không khớp: "+code);
   if(!"17".equals(text(config,"jdk_target",""))||!"exact_utf8_with_normalized_line_endings".equals(config.get("checker"))||!Boolean.FALSE.equals(config.get("network_access"))||!Boolean.TRUE.equals(config.get("sandbox_required")))throw new IllegalArgumentException("Judge config chưa hỗ trợ: "+code);
   if(integer(config,"time_limit_ms",0)<100||integer(config,"time_limit_ms",0)>5000||integer(config,"memory_limit_mb",0)<64||integer(config,"memory_limit_mb",0)>512||integer(config,"output_limit_kb",0)<1||integer(config,"output_limit_kb",0)>2048)throw new IllegalArgumentException("Giới hạn sandbox không hợp lệ: "+code);
   if(config.containsKey("structure_rules"))config.put("structure_rules",studyfix.assignment.grading.StructureRules.normalize(config.get("structure_rules")));String entry=text(config,"entry_file","");if(!entry.matches("[A-Za-z][A-Za-z0-9_]*\\.java"))throw new IllegalArgumentException("Tên file Java không hợp lệ.");String starter=textFile(local(dir,text(meta,"starter_template",""))),reference=textFile(local(dir,text(meta,"reference_solution","")));if(starter.getBytes(StandardCharsets.UTF_8).length>32768||reference.getBytes(StandardCharsets.UTF_8).length>32768)throw new IllegalArgumentException("Source vượt 32 KiB.");
   List<Exercise.TestCase> cases=new ArrayList<>();BigDecimal weights=BigDecimal.ZERO;Set<String> testIds=new HashSet<>();boolean publicTest=false,hiddenTest=false;
   for(Object row:list(meta.get("test_cases"))){var test=map(row);String tid=text(test,"id",""),visibility=text(test,"visibility","");if(!testIds.add(tid)||!Set.of("public","hidden").contains(visibility))throw new IllegalArgumentException("Test trùng hoặc visibility sai.");boolean hidden=visibility.equals("hidden");publicTest|=!hidden;hiddenTest|=hidden;String inputPath=text(test,structure.equals("PROGRAM")?("file_args0".equals(config.get("test_delivery"))?"fixture_file":"input_file"):"harness_snippet","");if(!inputPath.startsWith("tests/"+visibility+"/"))throw new IllegalArgumentException("Test path/visibility mismatch");String expectedPath=text(test,"expected_file","");if(!expectedPath.startsWith("tests/"+visibility+"/"))throw new IllegalArgumentException("Expected path/visibility mismatch");BigDecimal weight=new BigDecimal(String.valueOf(test.get("weight")));if(weight.signum()<=0)throw new IllegalArgumentException("Điểm test phải dương.");weights=weights.add(weight);String inputText=textFile(local(dir,inputPath));if(sha256.equals("8d5ee3b03609ca32290396b440cdabbf36801bbd755b68f4fa89ae816fefe24f")&&code.equals("JAVA092")&&"file_args0".equals(config.get("test_delivery"))&&inputText.endsWith("\n")){inputText=inputText.substring(0,inputText.length()-1);meta.put("import_corrections",List.of("JAVA092: removed one package-added final LF from each file fixture; expected outputs unchanged, original ZIP retained."));}cases.add(new Exercise.TestCase(inputText,textFile(local(dir,expectedPath)),weight.movePointRight(6).intValueExact(),hidden));}
   if(!publicTest||!hiddenTest||(header.containsKey("test_count")&&cases.size()!=integer(header,"test_count",-1))||weights.subtract(BigDecimal.valueOf(100)).abs().compareTo(new BigDecimal("0.000001"))>0)throw new IllegalArgumentException("Test count/score/public/hidden không hợp lệ: "+code);
   String statement=textFile(local(dir,text(meta,"statement_file","")))+studyfix.assignment.grading.StructureRules.statement(config.get("structure_rules"));Exercise exercise=new Exercise(code,text(meta,"title",""),text(meta,"week_title",""),text(meta,"difficulty",""),statement,"Xem định dạng và yêu cầu trong đề bài.","Xem định dạng và ví dụ kiểm thử công khai.","Xem mục ràng buộc trong đề bài.",starter,"",reference,ExerciseMode.BUILD_FROM_SCRATCH,starter,cases,structure,entry);
   parsed.add(new Problem(code,week,structure,entry,exercise,config,meta));count+=cases.size();
  }
  if(parsed.isEmpty())throw new IllegalArgumentException("Gói ZIP không có bài tập để nhập.");
  if(!ids.containsAll(mapping.keySet()))throw new IllegalArgumentException("Week tham chiếu mã bài không có trong manifest.");
  if((manifest.containsKey("total_problems")&&integer(manifest,"total_problems",-1)!=parsed.size())||(manifest.containsKey("week_count")&&integer(manifest,"week_count",-1)!=weeks.size()))throw new IllegalArgumentException("Số bài/Week khai báo trong manifest không khớp dữ liệu thực tế.");
  problems=List.copyOf(parsed);tests=count;
 }
 private String local(String dir,String relative){if(relative.isBlank()||relative.startsWith("/")||relative.contains("\\")||Arrays.stream(relative.split("/",-1)).anyMatch(s->s.equals("..")||s.equals(".")||s.isEmpty()))throw new IllegalArgumentException("Invalid package reference");return dir+relative;}
 private String textFile(String path)throws CharacterCodingException{byte[] bytes=files.get(path);if(bytes==null)throw new IllegalArgumentException("Thiếu file trong gói: "+path);return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString();}
 public Map<String,Object> preview(){return mapOf("sha256",sha256,"problems",problems.size(),"weeks",weeks.size(),"tests",tests,"structures",problems.stream().collect(java.util.stream.Collectors.groupingBy(Problem::structure,java.util.TreeMap::new,java.util.stream.Collectors.counting())),"corrections",problems.stream().flatMap(p->list(p.metadata().get("import_corrections")).stream()).distinct().toList(),"details",problems.stream().map(p->mapOf("code",p.code(),"title",p.exercise().title(),"week",p.week(),"structure",p.structure(),"tests",p.exercise().tests().size())).toList());}
}
